INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'遇到图中所示信号灯亮着，但栏杆还没落下，应怎样行驶？',1,'只要栏杆还没落下就继续行驶','如果没有看到列车驶来，可以加速横过道口','在道口的停止线以外停车等待','如果已过道口停止线，就可以急速通过','C',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'在高速公路上开车遇到图中所示的情况时，以下操作不正确的是什么？',1,'应该打开雾灯、近光灯、示廓灯、前后位灯，危险报警闪光灯','能见度低，应该与同车道前车间距保持—定距离','降低车速，防止紧急情况下无法及时制动','继续维持高速行驶，防止后面车辆堵塞','D',NULL,2,1,NULL,NOW());
