INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'如图所示，夜间驾驶机动车遇对方使用远光灯，无法看清前方路况时，以下做法正确的是什么？',1,'保持行驶方向和车速不变','自己也打开远光灯行驶','降低车速，谨慎会车','加速通过，尽快摆脱眩目光线','C',NULL,2,1,NULL,NOW());
