INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'行车中遇抢救伤员的救护车从本车道逆向驶来时，应怎样做？',1,'靠边减速或停车让行','占用其他车道行驶','加速变更车道避让','在原车道内继续行驶','A',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'如图所示，驾驶过程中遇到这种情况时，A车可以长鸣喇叭提醒道路养护车辆暂停喷水。',2,'正确','错误','','','B',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'驾驶机动车遇到前方低速行驶的洒水车作业时，以下做法错误的是什么？',1,'注意避让','若洒水车有指示箭头，在确保安全的情况下按箭头指示方向变更车道','若洒水车无指示箭头，在确保安全的情况下选择合适的车道变更','通过洒水车时应急加速通过','D',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'行车中遇到对向来车占道行驶，应怎样做？',1,'紧靠道路中心行驶','主动给对方让行','用大灯警示对方','逼对方靠右行驶','B',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'行车中发现前方道路拥堵时，应怎样做？',1,'寻找机会超越前车','从车辆空间穿插通过','减速停车，依次排队等候','鸣喇叭催促','C',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'发现前方道路堵塞，正确的做法是什么？',1,'继续穿插绕行','选择空当逐车超越','鸣喇叭示意前方车辆快速行驶','按顺序停车等候','D',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'车辆在拥挤路段低速行驶时，遇其他车辆强行插队，应怎样做？',1,'鸣喇叭警告，不得进入','加速行驶，紧跟前车，不让其进入','主动礼让，确保行车安全','挤靠“加塞”车辆，逼其离开','C',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'行车中需要借道绕过前方障碍物，但对向来车已接近障碍物时，应怎样做？',1,'降低速度或停车，让对向来车优先通行','加速提前抢过','鸣喇叭示意对向车辆让道','迅速占用车道，迫使对向来车停车让道','A',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'在堵车的交叉路口绿灯亮时，车辆应怎样做？',1,'可直接驶入交叉路口','不能驶入交叉路口','在保证安全的情况下驶入交叉路口','可借对向车道通过路口','B',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'如图所示，车辆在拥挤路段排队行驶时，遇有其他车辆强行穿插行驶，以下说法正确的是什么?',1,'迅速提高车速不让其穿插','持续鸣喇叭警告','迅速左转躲避','减速或停车让行','D',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'山区道路对安全行车的主要影响是什么？',1,'道路标志少','交通情况单一','坡长弯急，视距不足','车流密度大','C',NULL,2,1,NULL,NOW());
INSERT INTO question (cat_id,title,q_type,option_a,option_b,option_c,option_d,answer,analysis,difficulty,status,create_by,create_time) VALUES (@cid,'驾驶车辆行至道路急转弯处，应怎样做？',1,'借对向车道行驶','急剧制动低速通过','靠弯道外侧行驶','充分减速并靠右侧行驶','D',NULL,2,1,NULL,NOW());
